{"results": [{"id": "hp_doc_bffa6f49941771df17241f94cba1b55bf0da7fff2f087e9e5107ee6b3f70b403", "title": "Little Stranger (company)", "text": "Little Stranger, Inc. is a film and television production company owned by actress and producer Tina Fey with executive vice president and long-time collaborator Eric Gurian. It is known for producing the long-running series 30 Rock and Unbreakable Kimmy Schmidt.", "score": 19.3691}, {"id": "hp_doc_7eb8e93ef36009610708d2c186d8d6f460e1b2d6fde61676167a015497f89121", "title": "Bashu, the Little Stranger", "text": "Bashu, the Little Stranger (Persian: باشو غریبه کوچک‎ ‎ ), is a 1986 Iranian drama film directed by Bahram Beizai. The film was produced in 1986, and was released in 1989. This multi-ethnic film was the first Iranian film to make use of the northern language of Iran, Gilaki, in a serious context rather than comic relief. (Susan Taslimi playing the main character is Gilaki herself).", "score": 18.5258}, {"id": "hp_doc_227329ee2b6d6320722815e2cd905707395ac1f01ff1b8ba57779c3299cfe412", "title": "Eric Gurian", "text": "\"Eric Andrew Gurian\" is an American film and television producer, director and writer. He currently runs Tina Fey's production company Little Stranger.", "score": 14.8868}], "remaining_searches": 2}
